/** Root of a tree: a leaf carries `value`, a grouping carries `children`, never both. */
export type Data = { name: string; value?: number; children?: Data[] };

type Cell = d3.HierarchyRectangularNode<Data>;
type Rect = { x0: number; x1: number; y0: number; y1: number };

const DURATION = 750;
/** y is a depth index (0 = root), not a pixel. Hiding y0 < 1 drops the ring at the focus itself. */
const MIN_VISIBLE_DEPTH = 1;
/** Only two rings are ever shown beyond the focus, matching the fixed viewport radius. */
const MAX_VISIBLE_DEPTH = 3;
/** Arcs whose (angle * depth) area falls below this can't hold a label without overflow. */
const LABEL_MIN_AREA = 0.03;
const PAD_ANGLE = 0.005;

const format = d3.format(',d');

function pathOf(node: Cell): string {
  return node
    .ancestors()
    .map((a) => a.data.name)
    .reverse()
    .join('/');
}

/** Every arc takes the colour of the depth-1 genre it descends from. */
function genreOf(node: Cell): string {
  let current = node;
  while (current.depth > 1 && current.parent) current = current.parent;
  return current.data.name;
}

function arcVisible(d: Rect): boolean {
  return d.y1 <= MAX_VISIBLE_DEPTH && d.y0 >= MIN_VISIBLE_DEPTH && d.x1 > d.x0;
}

function labelVisible(d: Rect): boolean {
  return (
    d.y1 <= MAX_VISIBLE_DEPTH &&
    d.y0 >= MIN_VISIBLE_DEPTH &&
    (d.y1 - d.y0) * (d.x1 - d.x0) > LABEL_MIN_AREA
  );
}

function labelTransform(d: Rect, radius: number): string {
  const angle = ((d.x0 + d.x1) / 2) * (180 / Math.PI);
  const depth = ((d.y0 + d.y1) / 2) * radius;
  return `rotate(${angle - 90}) translate(${depth},0) rotate(${angle < 180 ? 0 : 180})`;
}

export default function ZoomableSunburst({
  data = catalog,
  width
}: {
  data?: Data;
  width: number;
}) {
  // Hooks run before the width===0 guard below.
  const side = Math.max(width, 1);
  const svgRef = useRef<SVGSVGElement>(null);

  // Angle x depth-index space is independent of pixel size, so this layout never changes with width.
  const root = useMemo(() => {
    const hierarchy = d3
      .hierarchy(data)
      .sum((d) => d.value ?? 0)
      .sort((a, b) => (b.value ?? 0) - (a.value ?? 0));
    return d3.partition<Data>().size([2 * Math.PI, hierarchy.height + 1])(hierarchy);
  }, [data]);

  const color = useMemo(
    () =>
      d3
        .scaleOrdinal<string, string>()
        .domain((data.children ?? []).map((d) => d.name))
        .range(d3.schemeObservable10),
    [data]
  );

  useEffect(() => {
    const element = svgRef.current;
    if (!element) return;

    const svg = d3.select(element);
    svg.selectAll('*').remove();

    const radius = side / 6;
    const nodes = root.descendants().slice(1); // the root itself has no arc

    const current = new Map<Cell, Rect>(
      root.descendants().map((d) => [d, { x0: d.x0, x1: d.x1, y0: d.y0, y1: d.y1 }])
    );
    const target = new Map<Cell, Rect>();
    const at = (d: Cell): Rect => current.get(d) ?? d;

    const arc = d3
      .arc<Rect>()
      .startAngle((d) => d.x0)
      .endAngle((d) => d.x1)
      .padAngle((d) => Math.min((d.x1 - d.x0) / 2, PAD_ANGLE))
      .padRadius(radius * 1.5)
      .innerRadius((d) => d.y0 * radius)
      .outerRadius((d) => Math.max(d.y0 * radius, d.y1 * radius - 1));

    const path = svg
      .append('g')
      .selectAll<SVGPathElement, Cell>('path')
      .data(nodes)
      .join('path')
      .attr('fill', (d) => color(genreOf(d)))
      .attr('fill-opacity', (d) => (arcVisible(at(d)) ? (d.children ? 0.6 : 0.4) : 0))
      .attr('pointer-events', (d) => (arcVisible(at(d)) ? 'auto' : 'none'))
      .attr('d', (d) => arc(at(d)) ?? '');

    path.filter((d) => !!d.children).style('cursor', 'pointer');
    path.append('title').text((d) => `${pathOf(d)}\n${format(d.value ?? 0)}`);

    const label = svg
      .append('g')
      .attr('pointer-events', 'none')
      .attr('text-anchor', 'middle')
      .attr('fill', 'var(--text)')
      .style('user-select', 'none')
      .selectAll<SVGTextElement, Cell>('text')
      .data(nodes)
      .join('text')
      .attr('dy', '0.35em')
      .attr('fill-opacity', (d) => Number(labelVisible(at(d))))
      .attr('transform', (d) => labelTransform(at(d), radius))
      .text((d) => d.data.name);

    let focus: Cell = root;

    // Rescale every node relative to the new focus and tween every arc/label towards it.
    function zoomTo(next: Cell) {
      if (next === focus) return;
      focus = next;

      root.each((d) =>
        target.set(d, {
          x0: Math.max(0, Math.min(1, (d.x0 - next.x0) / (next.x1 - next.x0))) * 2 * Math.PI,
          x1: Math.max(0, Math.min(1, (d.x1 - next.x0) / (next.x1 - next.x0))) * 2 * Math.PI,
          y0: Math.max(0, d.y0 - next.depth),
          y1: Math.max(0, d.y1 - next.depth)
        })
      );

      path
        .filter(function (d) {
          return Number(this.getAttribute('fill-opacity')) > 0 || arcVisible(target.get(d)!);
        })
        .transition()
        .duration(DURATION)
        .attr('fill-opacity', (d) => (arcVisible(target.get(d)!) ? (d.children ? 0.6 : 0.4) : 0))
        .attr('pointer-events', (d) => (arcVisible(target.get(d)!) ? 'auto' : 'none'))
        .attrTween('d', (d) => {
          const interpolate = d3.interpolate(at(d), target.get(d)!);
          return (t) => {
            const value = interpolate(t);
            current.set(d, value);
            return arc(value) ?? '';
          };
        });

      label
        .filter(function (d) {
          return Number(this.getAttribute('fill-opacity')) > 0 || labelVisible(target.get(d)!);
        })
        .transition()
        .duration(DURATION)
        .attr('fill-opacity', (d) => Number(labelVisible(target.get(d)!)))
        .attrTween('transform', (d) => {
          const interpolate = d3.interpolate(at(d), target.get(d)!);
          return (t) => labelTransform(interpolate(t), radius);
        });
    }

    path.filter((d) => !!d.children).on('click', (_event: MouseEvent, d: Cell) => zoomTo(d));

    const center = svg
      .append('circle')
      .attr('r', radius)
      .attr('fill', 'none')
      .attr('pointer-events', 'all')
      .style('cursor', 'pointer')
      .on('click', () => zoomTo(focus.parent ?? root));

    return () => {
      svg.interrupt();
      svg.selectAll('*').interrupt();
      path.on('click', null);
      center.on('click', null);
      svg.selectAll('*').remove();
    };
  }, [root, color, side]);

  if (width === 0) return null;

  return (
    <svg
      ref={svgRef}
      viewBox={`${-side / 2} ${-side / 2} ${side} ${side}`}
      width="100%"
      height={side}
      role="img"
      aria-label="Zoomable sunburst of a streaming catalog; click a wedge to zoom in, the center to zoom out"
      style={{ display: 'block', font: '10px sans-serif' }}
    />
  );
}
